export const initialChronicle=()=>({seen:[],choices:{},finds:[]});
export function validChronicle(raw){
 if(raw===undefined)return initialChronicle();if(!raw||!Array.isArray(raw.seen)||raw.seen.length>8||new Set(raw.seen).size!==raw.seen.length||raw.seen.some(id=>!Object.hasOwn(SCENES,id))||!Array.isArray(raw.finds)||raw.finds.length>6||new Set(raw.finds).size!==raw.finds.length||raw.finds.some(id=>!Object.hasOwn(DISCOVERIES,id))||!raw.choices||Array.isArray(raw.choices)||typeof raw.choices!=='object'||Object.entries(raw.choices).some(([id,v])=>!raw.seen.includes(id)||![0,1].includes(v))||raw.seen.some(id=>!Object.hasOwn(raw.choices,id)))return null;
 return {seen:[...raw.seen],choices:{...raw.choices},finds:[...raw.finds]};
}
export const canViewScene=(s,id)=>Object.hasOwn(SCENES,id)&&s.visited.includes(SCENES[id].area)&&s.seals.length>=(SCENES[id].seals||0)&&!s.battle;
export function finishScene(s,id,choice){if(!canViewScene(s,id)||![0,1].includes(choice)||s.chronicle.seen.includes(id))return false;s.chronicle.seen.push(id);s.chronicle.choices[id]=choice;return true;}
export function discover(s,id){const d=DISCOVERIES[id];if(!d||s.battle||s.interior||s.area!==d.area||s.chronicle.finds.includes(id))return false;s.chronicle.finds.push(id);if(!s.growth.inventory.includes(d.reward))s.growth.inventory.push(d.reward);return true;}
export const chapter=s=>s.ended?{number:4,title:'A light answered',goal:'The beacon shines. There are still neighbours, stories and hidden things to find.'}:s.seals.length===4?{number:3,title:'The answering light',goal:'Return to the Last Beacon and face the Hollow Warden.'}:s.seals.length>=2?{number:2,title:'The names we left out',goal:'Follow the remaining clues in the archive and observatory. Restore all four seals.'}:{number:1,title:'To whoever comes next',goal:'Meet the keepers. Restore the mechanisms in the woods, mill, archive and observatory.'};
