const refs={type:'array',minItems:1,maxItems:4,items:text(100)};
const room=obj({title:text(80),description:text(600),clue:obj({title:text(80),text:text(1000),sourceRefs:refs}),npc:obj({name:text(60),dialogue:text(1000),sourceRefs:refs})});
