import {readReviewedGames,storeReviewedGame} from './reviewed-games.js';
import {conceptTrail,CONCEPT_STATUS} from '../concept-progress.js';
import {learningJournal,gameSaveKey} from './learning-client.js';
import {recommendations,normaliseProfile} from './learning-model.js';
import {mountJourney} from './journey-ui.js';
import {EXTENDED_PACKS} from './extended-packs.js';
import {EXTENDED_IDS} from './extended-content.js';
import {mountExtended} from './extended-ui.js';
import {ADVENTURE_PACKS} from './adventure-content.js';
import {TOWN_PACKS} from './town-packs.js';
import {mountTown} from './town-ui.js';
import {DRAFT_PACKS} from './draft-content.js';
import {mountAdventure} from './adventure-ui.js';
import {mountDraft} from './draft-ui.js';
import {validatePlayableContent,GAME_TEMPLATES,gameReviewHTML} from './content-registry.js';
import {ResourceWorkshop} from '../resource-workshop.js';
import './mode-style.css';
let launchSequence=0;
const root=document.querySelector('#game-library'),layer=document.querySelector('#library-layer');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let assets={},active=null,custom=[],notice='',modal=null,returnFocus=null;
function readCustom(){try{custom=readReviewedGames(learningJournal.storage)}catch{notice='Saved imported games could not be read. The included adventures are ready to play.';custom=[]}}
function allPacks(){return [...new Map([...ADVENTURE_PACKS,...DRAFT_PACKS,...TOWN_PACKS,...EXTENDED_PACKS,...custom].map(pack=>[pack.id,pack])).values()]}
function register(pack){const clean=validatePlayableContent(pack);if(clean.template==='underlight-v1')throw Error('Open this chapter through the RPG.');try{custom=storeReviewedGame(learningJournal.storage,clean)}catch{custom=[clean,...custom.filter(p=>p.id!==clean.id)].slice(0,20);notice='This browser could not update its saved game library. Existing data is preserved. You can play now and download the chapter from the Resource Library for later.'}return clean}
function destroy(){active?.destroy();active=null;root.innerHTML=''}
function closeModal(){workshop.extraction?.abort();modal=null;layer.innerHTML='';layer.hidden=true;returnFocus?.focus?.()}
const button=(text,action,attrs='',kind='')=>`<button type="button" data-act="${action}" ${attrs} class="${kind}">${text}</button>`;
function wrap(html){return `<div class="scrim"><section class="panel" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button type="button" class="modal-close" data-act="close" aria-label="Close dialog">×</button>${html}</section></div>`}
function studyTrailHTML(){const trail=conceptTrail(allPacks(),learningJournal.records);return `<h2 id="modal-title">Your study trail</h2><p>${esc(learningJournal.profile.goal||'Choose an idea to explore, or revisit one that needed another look.')}</p><p class="muted">Objectives are mapped to specific activities and sources. These observations suggest practice, never grades or fixed learning styles. Every game stays available.</p><div class="study-trail">${trail.map(c=>`<article class="study-concept"><div><span class="study-status">${esc(CONCEPT_STATUS[c.status])}</span><h3>${esc(c.objective)}</h3><p>${esc(c.reason)}</p>${c.preparation.length?`<p class="study-preparation">Useful preparation: ${esc(c.preparation.map(p=>p.objective).join('; '))}.</p>`:''}<small>${c.observations.length} mapped observation${c.observations.length===1?'':'s'} · ${c.activities.length} activit${c.activities.length===1?'y':'ies'}${c.last?' · Last played '+esc(new Date(c.last).toLocaleDateString()):''}</small></div>${button('Open concept','study-concept',`data-concept="${c.key}"`)}</article>`).join('')||'<p>Map concepts while revising a chapter to connect its activities here.</p>'}</div>${button('Learning goal and preferences','study-preferences')}`;}
function studyConceptHTML(){const c=conceptTrail(allPacks(),learningJournal.records).find(c=>c.key===modal.concept);if(!c)return '<h2 id="modal-title">This concept is no longer available</h2>';return `<h2 id="modal-title">${esc(c.objective)}</h2><p>${esc(c.reason)}</p><section class="study-scaffold"><h3>Before you play</h3><p>Explain the idea in your own words. Predict how it might apply in a different example, then check the evidence below.</p>${c.preparation.length?'<h3>Useful preparation</h3>'+c.preparation.map(p=>button(esc(p.objective),'study-concept',`data-concept="${p.key}"`)).join(''):''}<details><summary>Read the supporting evidence</summary>${c.sources.map(s=>`<blockquote>${esc(s.excerpt)}<footer>${esc(s.title)} — ${esc(s.locator)}</footer></blockquote>`).join('')}</details><p>After playing, compare your explanation with the source. Identify one detail you would change or explain more carefully.</p></section><h3>Try it in a game</h3><p>The game opens at your saved position. Use its journal or start a fresh run to revisit the named activity.</p>${c.activities.map(a=>`<article class="resource-row"><div><b>${esc(a.title)}</b><small>${esc(a.label)}</small></div>${button('Open game','study-play',`data-pack="${esc(a.packId)}" data-kind="${a.kind}"`)}</article>`).join('')}${button('Back to study trail','study-trail')}`;}
function journalHTML(){const p=learningJournal.profile;return `<h2 id="modal-title">Your learning journal</h2><p>Keep your learning goal and preferred activities together. Suggestions use practice observations, never game scores as grades.</p><label for="learner-goal">Learning goal</label><textarea id="learner-goal" rows="3" maxlength="1200">${esc(p.goal)}</textarea><label for="learner-context">Your level and needs</label><input id="learner-context" maxlength="240" value="${esc(p.context)}"><fieldset><legend>Formats you enjoy</legend>${GAME_TEMPLATES.map(t=>`<label class="workshop-check"><input type="checkbox" data-preference="${t.id}" ${p.formats.includes(t.id)?'checked':''}>${esc(t.name)}</label>`).join('')}</fieldset><p class="muted">${learningJournal.user?'Saved to your learner account.':'Saved on this device. Sign in to save across devices.'} These preferences fill the next game-creation form; they do not trigger generation.</p>${button('Save preferences','learner-save','','primary')}${learningJournal.profileConflict?button('Load cloud preferences','learner-profile-reload'):''}<p role="status">${esc(modal?.feedback||learningJournal.notice)}</p><h3>Recent practice</h3>${learningJournal.records.slice(0,12).map(r=>`<article class="resource-row"><div><b>${esc(r.summary.title)}</b><small>${r.summary.completed?'Completed a run':'In progress'} · ${r.summary.observations.filter(o=>o.correct===true&&(o.attempts>1||o.assisted)).length} questions revisited with support${learningJournal.user?' · '+(r.conflict?'Different cloud save':r.pending?'Waiting to sync':'Saved to account'):''}</small>${r.error?'<p>'+esc(r.error)+'</p>':''}${r.conflict?'<p>Continue cloud progress to replace this device’s run, or use this device’s run for your account.</p>':''}</div>${learningJournal.user?'<div class=journal-save-actions><button data-act=learner-cloud data-key="'+esc(r.key)+'">Continue cloud save</button>'+(r.snapshot?'<button data-act=learner-device data-key="'+esc(r.key)+'">Use device save</button>':'')+'</div>':''}</article>`).join('')||'<p>Play a game to start your journal.</p>'}`;}
function recommendationsHTML(){const list=recommendations(allPacks(),learningJournal.records,learningJournal.profile);return list.length?`<section class="learning-next"><h2>Your next chapter</h2><p>Suggestions are optional. Shared passages can cover different ideas.</p><div>${list.map(r=>`<article><span>${esc(r.label)}</span><h3>${esc(allPacks().find(p=>p.id===r.id).title)}</h3><p>${esc(r.reason)}</p><button data-recommend="${esc(r.id)}" data-kind="${esc(r.kind)}">Open game</button></article>`).join('')}</div></section>`:'';}
function renderModal(){const focusId=layer.contains(document.activeElement)?document.activeElement.id:null;if(!modal){closeModal();return}layer.hidden=false;if(modal.kind==='study-trail'){layer.innerHTML=wrap(studyTrailHTML())}else if(modal.kind==='study-concept'){layer.innerHTML=wrap(studyConceptHTML())}else if(modal.kind==='learning-journal'){layer.innerHTML=wrap(journalHTML())}else if(modal.kind==='import-review'){layer.innerHTML=wrap(`<p>Review imported game</p>${[...ADVENTURE_PACKS,...DRAFT_PACKS,...TOWN_PACKS,...EXTENDED_PACKS].some(p=>p.id===modal.draft.id)?'<p class="workshop-notice">This file will become this browser’s version of the included story with the same ID.</p>':''}<h2 id="modal-title">${esc(modal.draft.title)}</h2><p>${esc(modal.draft.hook)}</p>${gameReviewHTML(modal.draft,esc)}<label class="workshop-check"><input id="import-confirm" type="checkbox" ${modal.confirmed?'checked':''}>I checked the learning content and its sources.</label><div class="row">${button('Play reviewed game','import-use',modal.confirmed?'':'disabled','primary')}${button('Back to games','close')}</div>`)}else{layer.innerHTML=workshop.panel(modal,{esc,button,wrap})||wrap('<h2 id="modal-title">Open the RPG to use this chapter</h2><a href="/">Return to Lanternbound</a>')}if(focusId)layer.querySelector('#'+CSS.escape(focusId))?.focus(); }
function openModal(m){if(!modal)returnFocus=document.activeElement;modal=m;renderModal();layer.querySelector('h2')?.setAttribute('tabindex','-1');layer.querySelector('h2')?.focus()}
const context={get:()=>({pack:{id:'mosaic-games'},get modal(){return modal},openModal,renderModal}),download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}};
const workshop=new ResourceWorkshop(context,{template:'adventure-v1',templates:['adventure-v1','draft-v1','town-v1',...EXTENDED_IDS],onActivate:async draft=>{start(register(draft))}});
function library(template='adventure-v1'){workshop.template=template;void workshop.open()}
function hasEarlier(pack){try{return !!learningJournal.storage.getItem(gameSaveKey(pack,'classic'))}catch{return false}}
function poster(template,title,desc,image){const packs=allPacks().filter(p=>p.template===template);return `<article class="game-poster ${template==='draft-v1'?'draft-poster':''}"><div class="poster-art" style="background-image:url('${esc(image)}')"><span class="poster-type">${esc(GAME_TEMPLATES.find(t=>t.id===template)?.name||'Learning game')}</span><h2>${title}</h2></div><div class="poster-content"><p>${desc}</p><label for="choose-${template}">Choose a story</label><select id="choose-${template}">${packs.map(p=>`<option value="${esc(p.id)}">${esc(p.title)}</option>`).join('')}</select><div class="poster-actions"><button class="primary" data-play="${template}">Play</button>${EXTENDED_IDS.includes(template)?`<button data-classic="${template}" ${hasEarlier(packs[0])?'':'hidden'}>Continue earlier run</button>`:''}<button data-create="${template}">Create from your material</button></div></div></article>`}
function hub(){readCustom();launchSequence++;destroy();closeModal();window.scrollTo({top:0,left:0,behavior:'instant'});history.replaceState(null,'','/modes.html');root.innerHTML=`<header class="library-heading"><a href="/" class="library-brand">✦ Lanternbound</a><nav aria-label="Game library"><a href="/studio.html">Learning studio</a><a href="/account.html">${learningJournal.user?esc(learningJournal.user.name||'Account'):'Sign in'}</a><a href="/">Return to the RPG</a><button data-study>Study trail</button><button data-journal>Your learning journal</button><button data-library>Resource library</button></nav></header><section class="library-intro"><h1>A new way into every subject.</h1><p>Follow a story. Make a choice. Find out why it matters.</p></section>${recommendationsHTML()}<div class="game-posters">${poster('adventure-v1','The Thread Atlas','Step into an illustrated world. Read its clues, talk to its keepers and put your discoveries to work.',assets.rooms?.workshop)}${poster('draft-v1','Turning Points','Build a set of five choices. Discover how they work together when the world changes around them.',assets.tables?.draft||assets.rooms?.archive)}${poster('town-v1','The Living Town','Build a connected town. Balance a working economy with the people and places it serves.','/game-modes/town-art/town-poster.png')}${poster('novel-v1','Letters from Riverlight','Read the room, follow the evidence and decide which promise the town keeps.',assets.extended.backgrounds.vn.url)}${poster('quiz-v1','The Star Archive','Explore a branching constellation. Plan your route, use your lenses and connect eight ideas.',assets.extended.backgrounds.quiz.url)}${poster('sports-v1','Riverlight Cup','Read the opposition, choose your formation and create the opening. A new seed changes the match.',assets.extended.backgrounds.sports.url)}${poster('merge-v1','The Makers Guild','Combine ideas at the workbench. Unlock six guild commissions, or test your material efficiency.',assets.extended.backgrounds.merge.url)}<article class="game-poster rpg-poster"><div class="poster-art" style="background-image:url('${esc(assets.rooms?.woods||assets.rooms?.workshop)}')"><span class="poster-type">3D RPG</span><h2>Lanternbound</h2></div><div class="poster-content"><p>Return to the three-dimensional world of towns, companions, battles and learning quests.</p><a class="rpg-play-link" href="/">Enter Lanternbound</a></div></article></div><section class="library-foot"><div><h2>Your material, a different adventure.</h2><p>Upload and review a source, choose a game format, then inspect what Muse Wonder creates. Included examples can be played immediately.</p></div><div class="library-file"><label for="game-import">Import a reviewed game file</label><input type="file" id="game-import" accept=".json,application/json"><p class="library-notice" role="status">${esc(notice)}</p></div></section>`;root.querySelectorAll('[data-play]').forEach(b=>b.addEventListener('click',()=>{const id=root.querySelector('#choose-'+b.dataset.play).value;const pack=allPacks().find(p=>p.id===id&&p.template===b.dataset.play);if(pack)start(pack)}));root.querySelectorAll('[data-classic]').forEach(b=>root.querySelector('#choose-'+b.dataset.classic).addEventListener('change',e=>{b.hidden=!hasEarlier(allPacks().find(p=>p.id===e.target.value))}));root.querySelectorAll('[data-classic]').forEach(b=>b.addEventListener('click',()=>{const p=allPacks().find(p=>p.id===root.querySelector('#choose-'+b.dataset.classic).value);if(p)start(p,true)}));root.querySelectorAll('[data-create]').forEach(b=>b.addEventListener('click',()=>library(b.dataset.create)));root.querySelector('[data-study]').addEventListener('click',()=>openModal({kind:'study-trail'}));root.querySelector('[data-journal]').addEventListener('click',()=>openModal({kind:'learning-journal'}));root.querySelectorAll('[data-recommend]').forEach(b=>b.addEventListener('click',()=>{const p=allPacks().find(p=>p.id===b.dataset.recommend);if(p)start(p,b.dataset.kind==='classic')}));root.querySelector('[data-library]').addEventListener('click',()=>library());root.querySelector('#game-import').addEventListener('change',async e=>{try{const f=e.target.files?.[0];if(!f)return;if(f.size>131072)throw Error('Choose a JSON game file below 128 KB.');const draft=validatePlayableContent(await f.text());if(draft.template==='underlight-v1')throw Error('Import this 3D chapter through the RPG Chapter workshop.');openModal({kind:'import-review',draft})}catch(err){notice=err.message;hub()}})}
async function start(pack,classic=false){
 const launch=++launchSequence;
 try{
  const clean=validatePlayableContent(pack);
  if(clean.template==='underlight-v1')throw Error('This chapter belongs in the 3D RPG.');
  destroy();closeModal();root.innerHTML='<p class="library-error">Restoring your journey…</p>';
  await learningJournal.prepare(clean,EXTENDED_IDS.includes(clean.template)&&!classic?'journey':'classic');
  if(launch!==launchSequence)return;
  history.replaceState(null,'','/modes.html?game='+encodeURIComponent(clean.id)+(classic?'&classic=1':''));
  const mount=EXTENDED_IDS.includes(clean.template)?(classic?mountExtended:mountJourney):clean.template==='town-v1'?mountTown:clean.template==='draft-v1'?mountDraft:mountAdventure;
  active=mount(root,{pack:clean,assets,storage:learningJournal.storage,onExit:hub,onLibrary:()=>library(clean.template),onClassic:()=>start(clean,true),onProgress:data=>learningJournal.observe(data)});
  root.focus({preventScroll:true});window.scrollTo({top:0,left:0,behavior:'instant'});
 }catch(error){if(launch===launchSequence){root.innerHTML=`<section class="library-error"><h1>This journey could not open</h1><p>${esc(error.message)}</p><button id="return-games">Return to games</button></section>`;root.querySelector('#return-games').addEventListener('click',hub);}}
}
layer.addEventListener('click',async e=>{const b=e.target.closest('button[data-act]');if(!b||b.disabled)return;const action=b.dataset.act;try{if(action==='study-trail'){openModal({kind:'study-trail'});return}if(action==='study-preferences'){openModal({kind:'learning-journal'});return}if(action==='study-concept'){openModal({kind:'study-concept',concept:b.dataset.concept});return}if(action==='study-play'){const p=allPacks().find(p=>p.id===b.dataset.pack);if(p)await start(p,b.dataset.kind==='classic');return}if(action==='learner-profile-reload'){await learningJournal.reloadProfile();modal.feedback=learningJournal.notice;renderModal();return;}if(['learner-cloud','learner-device'].includes(action)){const r=learningJournal.records.find(r=>r.key===b.dataset.key);if(r?.summary.kind==='rpg'){location.assign('/?'+new URLSearchParams({rpg:r.summary.packId,hash:r.summary.contentHash}));return;}const p=allPacks().find(p=>p.id===r?.summary.packId);if(!p)throw Error('Open this game from the Resource Library first.');await learningJournal.resolveSave(p,r.summary.kind,action==='learner-cloud');await start(p,r.summary.kind==='classic');return;}if(action==='learner-save'){const profile=normaliseProfile({...learningJournal.profile,goal:layer.querySelector('#learner-goal').value,context:layer.querySelector('#learner-context').value,formats:[...layer.querySelectorAll('[data-preference]:checked')].map(e=>e.dataset.preference)});await learningJournal.saveProfile(profile);modal.feedback=learningJournal.notice;renderModal();return}if(action==='close'){workshop.extraction?.abort();closeModal();return}if(action==='import-use'&&modal?.confirmed){start(register(modal.draft));return}await workshop.act(action,b)}catch(err){if(modal){modal.feedback=err.message;renderModal()}}});
for(const type of ['input','change'])layer.addEventListener(type,async e=>{if(type==='input'&&e.target.type==='file')return;if(e.target.id==='import-confirm'){modal.confirmed=e.target.checked;renderModal();return}await workshop.change(e)});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){e.preventDefault();closeModal();return}if(e.key==='Tab'){const nodes=[...layer.querySelectorAll('button:not(:disabled),a,input:not(:disabled),select,textarea,summary')].filter(n=>n.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||!layer.contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!layer.contains(document.activeElement))){e.preventDefault();first.focus()}}});
async function boot(){try{await learningJournal.connect();const response=await fetch('/game-modes/art/manifest.json');if(!response.ok)throw Error('The illustrated asset library did not load. Please reload.');assets=await response.json();const townResponse=await fetch('/game-modes/town-art/manifest.json');if(!townResponse.ok)throw Error('Town artwork did not load. Please reload.');assets.town=await townResponse.json();const extendedResponse=await fetch('/game-modes/extended-art/manifest.json');if(!extendedResponse.ok)throw Error('The new game artwork did not load. Please reload.');assets.extended=await extendedResponse.json();const depthResponse=await fetch('/game-modes/depth-art/manifest.json');if(depthResponse.ok)assets.depth=await depthResponse.json();readCustom();const params=new URLSearchParams(location.search),job=params.get('job'),id=params.get('game');if(job){const data=await workshop.request('jobs/'+encodeURIComponent(job));if(data.job.status!=='published')throw Error('Review this generated game in the Resource Library before playing.');start(register(data.job.draft))}else{const found=allPacks().find(p=>p.id===id);if(found)start(found,params.get('classic')==='1');else{hub();if(params.get('workshop')==='1'){workshop.form.goal=(params.get('goal')||learningJournal.profile.goal).slice(0,1200);workshop.form.level=(params.get('level')||learningJournal.profile.context||'New to this topic').slice(0,240);void workshop.open();}}}}catch(e){root.innerHTML=`<section class="library-error"><h1>One moment…</h1><p>${esc(e.message)}</p><button id="retry-library">Try again</button><a href="/">Return to the RPG</a></section>`;root.querySelector('#retry-library').addEventListener('click',()=>location.reload())}}
boot();
